# The decoder... decodes the data (decoder.py)
import decoder

def decode(string):
    # decodes the given str and returns nbt data
    data = decoder.decodeData(string)
    return data

def prettydecode(string):
    # decodes the given str and returns a string displaying the nbt data structure
    data = decoder.decodeData(string)
    data = data.pretty_tree()
    return data

def pretty(data):
    # converts the given nbt object and returns a string displaying the nbt data structure
    data = data.pretty_tree()
    return data

def invItemList(inv):
    # Returns a list of the item ids of the given inventory
    items = []

    for item in inv["i"]:
        try:
            items.append(item['tag']['ExtraAttributes']['id'])
        except KeyError:
            continue

    return items

